UPDATE companies SET description='ProCare Medical Equipment was founded in 2007 and is headquartered in Meridian, Idaho. The company began as a medical equipment provider focused on serving patient care facilities in the region.

ProCare specializes in the rental, sale, and servicing of durable medical equipment (DME) for healthcare facilities. Its services include equipment rental programs, repair and preventative maintenance on most brands, cleaning and sanitization under its proprietary Patient Ready Certified™ program, liquid oxygen delivery with respiratory therapy support, and continuing education for healthcare professionals. The company also assembles custom equipment packages tailored to skilled nursing, hospice, rehabilitation, and VA facilities.

ProCare serves long-term care facilities, rehabilitation and transitional care centers, hospice agencies, and VA or government healthcare facilities across Idaho and eastern Oregon. Its customer base includes skilled nursing facilities seeking wound care and bariatric equipment, hospice providers needing comfort-focused surfaces and bed frames, and government facilities requiring respiratory and rehabilitation solutions.

The company emphasizes compassionate, on-time service and a holistic approach called 360° Servicing, which integrates rental, repair, cleaning, and education into a single solution. Its Patient Ready Certified™ seal guarantees equipment sanitized beyond industry standards, and its Sunrise Sessions provide continuing education for clinical staff. ProCare states its mission is to empower health with innovative solutions and to become the primary DME provider for professional care agencies in its service area.', certifications=ARRAY[]::text[], profile='{"capabilities": ["DME rental", "DME sales", "DME repair and preventative maintenance", "Equipment cleaning and sanitization (Patient Ready Certified\u2122)", "Liquid oxygen delivery and respiratory therapy services", "Continuing education (Sunrise Sessions)", "Custom equipment package configuration", "Wound care equipment supply", "Bariatric equipment supply", "Respiratory equipment supply", "Rehabilitation equipment supply", "Surface and bed frame supply"], "industries": ["Long-term care", "Rehabilitation and transitional care", "Hospice care", "VA and government healthcare"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Patient Ready Certified\u2122 sanitization program", "360\u00b0 Servicing integrating rental, repair, cleaning, and education", "Liquid oxygen delivery with respiratory therapist setup in Treasure Valley", "Sunrise Sessions continuing education for clinical staff", "Custom equipment packages configured per facility"], "facts_used": ["Founded 2007 -> /about", "Headquartered in Meridian, Idaho -> /about, /", "Specializes in DME rental to patient care facilities -> /, /about", "Focus on wound care and bariatrics -> /", "Services: rentals, repairs, cleanings, liquid oxygen/respiratory therapy, education -> /, /services", "Patient Ready Certified\u2122 program -> /, /services", "360\u00b0 Servicing concept -> /services", "Sunrise Sessions continuing education -> /services", "Custom equipment packages -> /, /services", "Industries served: long-term care, rehab/transitional, hospice, VA/government -> /, /about", "Service area: Idaho and eastern Oregon -> /about", "Treasure Valley service area for respiratory -> /", "Address: 573 S Locust Grove Rd, Meridian, ID 83642 -> /, /about, /services"], "company_type": "Distributor / reseller", "makes_products": "no", "type_evidence": "ProCare Medical Equipment specializes in the rental of durable medical equipment (DME) to patient care facilities.", "founded_year": "2007", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='procare-medical-equipment' AND approved AND profile IS NULL;
UPDATE companies SET description='ProStock Automotive operates from its corporate office in Saddle Brook, New Jersey, where it has served the tri-state automotive aftermarket for more than 30 years. The locally owned company maintains a network of 12 locations across northern New Jersey, New York, and Connecticut, including branches in East Hanover, Midland Park, Montclair, Ridgefield, Waterbury, and Totowa.

The distributor supplies professional installers with a curated selection of brand-name parts for domestic, Asian, and European vehicles, carrying lines such as Denso, Bosch, Gates, Moog, and Delco. A company-owned fleet of GPS-tracked vehicles runs on a dispatched delivery system, staffed by long-tenured drivers who provide consistent daily service to repair shops. Counter operations are handled by more than 25 specialists, each averaging two decades of experience, supported by 24/7 online ordering through ACDelco Connect, NexPart, Parts Tech, and the company''s own WebLink catalog.

The company emphasizes quality over price substitution, with buyers selecting brands to ensure installers can work with confidence. Returns are processed through a dedicated department that issues credits via fax or email within 24 hours.

Founded on the principle of "Professional service, always in stock," ProStock positions itself as large enough to offer competitive pricing and inventory depth while remaining small enough to respond to individual shop needs. The business model combines local inventory availability with digital ordering tools that allow technicians to look up parts by VIN or license plate from a smartphone.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Auto parts distribution", "Same-day delivery service", "Online parts ordering (ACDelco Connect, NexPart, Parts Tech, WebLink)", "VIN and license plate parts lookup", "Counter sales support", "Returns and core processing", "Inventory management for professional installers"], "industries": ["Automotive aftermarket", "Professional automotive repair", "Fleet maintenance", "Automotive parts distribution"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Company-owned GPS-equipped delivery fleet with long-tenured drivers", "Returns credited within 24 hours via fax or email", "25+ counter specialists averaging 20 years experience each", "24/7 online ordering through ACDelco Connect, NexPart, Parts Tech, and WebLink", "12 locations across New Jersey, New York, and Connecticut"], "facts_used": ["Headquarters in Saddle Brook, NJ -> db", "12 locations across NJ, NY, CT -> /", "Over 30 years in business -> /, /about-us", "Locally owned -> /about-us", "Brands carried: Denso, Bosch, Gates, Moog, Delco -> /about-us", "Company-owned GPS delivery fleet -> /about-us", "25+ counter specialists with avg 20 years experience -> /about-us", "Online ordering via ACDelco Connect, NexPart, Parts Tech, WebLink -> /about-us", "Returns processed within 24 hours -> /about-us", "Serves professional installers in tri-state area -> /, /about-us"], "company_type": "Distributor / reseller", "makes_products": "no", "type_evidence": "We''re a leading supplier to the Professional Installer of auto parts and equipment in New Jersey, New York and Connecticut.", "founded_year": "", "employee_count": "25+ counter specialists", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='prostock-auto-parts-saddle-brook' AND approved AND profile IS NULL;
UPDATE companies SET description='Process Equipment, based in New Waterford, Ohio, operates as an independent dealer of material handlers, attachments, and recycling equipment. The company has served the scrap, recycling, waste, demolition, port, and industrial material-handling sectors for over three decades, building a reputation for supplying work-ready machinery from major OEMs.

The company stocks a large inventory of new, used, and rebuilt material handlers from brands such as Caterpillar, Sennebogen, Liebherr, and Fuchs, along with attachments including orange-peel grapples from Rotobec, Pro-Lift, and Kinshofer, as well as magnets and shredders from Wolf and Hammel. Process Equipment buys each machine, subjects it to a 210-point internal inspection supplemented by third-party verification, and then offers it with installation support, parts supply, and service. New inventory arrives weekly, and the company arranges nationwide and international shipping.

Customers include scrap yards, materials recovery facilities, timber and lumber mills, port terminals, demolition contractors, and steel mills. Typical applications cover scrap and metal recycling, waste transfer and MRF operations, bulk material handling at ports, and timber yard processing.

Process Equipment distinguishes itself by not acting as a broker; it takes ownership of every unit, reconditions it to a consistent quality standard, and provides transparent documentation such as video walkthroughs, detailed photo packages, and fluid analysis. The goal is to deliver a purchasing experience close to buying new without the new-machine price, backed by independent, expert advice.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Equipment sales (new, used, rebuilt material handlers)", "Attachment sales (grapples, clamshell buckets, magnets, generators)", "Shredder sales (Hammel, Wolf)", "Installation support", "Parts supply", "Service and maintenance", "Third-party inspections", "Video walkthroughs", "Detailed photo packages", "Fluid analysis", "210-point internal inspection", "Fast sourcing for hard-to-find machines", "Nationwide shipping", "International shipping", "Attachment pairing expertise", "Shredding baled aluminum extrusion"], "industries": ["Scrap metal recycling", "Waste transfer & MRF facilities", "Ports & bulk material handling", "Timber yards & industrial operations", "Demolition", "Steel mills", "Materials recovery facilities", "Timber/lumber mills", "Port facilities", "Demolition contractors"], "materials": ["Scrap metal", "Aluminum extrusion", "Waste", "Timber", "Bulk materials"], "equipment": ["Caterpillar MH series material handlers", "Sennebogen material handlers", "Liebherr LH series material handlers", "Fuchs material handlers", "Wolf shredders", "Hammel shredders", "Rotobec orange peel grapples", "Pro-Lift grapples", "Kinshofer clamshell buckets", "Magnets (41\" to 67\")"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Largest independent dealer for material handlers and attachments", "Not a broker; buys and takes possession of all equipment", "210-point internal inspection plus third-party verification", "Transparent purchasing with video walkthroughs and fluid analysis", "Authorized dealer for Hammel and Wolf shredders in North America", "Nationwide and international shipping"], "facts_used": ["Headquarters: New Waterford, Ohio -> db", "Independent dealer of material handlers and attachments -> /", "Authorized dealer for Hammel and Wolf shredders in North America -> /", "210-point inspection process with third-party verification -> /", "Industries served: scrap yards, MRF, timber mills, ports, demolition, steel mills -> /", "Services: installation, parts, service, shipping -> /", "Brands carried: Caterpillar, Sennebogen, Liebherr, Fuchs, Wolf, Hammel, Rotobec, Pro-Lift, Kinshofer -> /", "Transparent purchasing with video walkthroughs, photo packages, fluid analysis -> /", "New inventory arrives weekly -> /", "Nationwide and international shipping -> /"], "company_type": "Distributor / reseller", "makes_products": "no", "type_evidence": "We are not a broker. We offer you equipment that we buy, take possession of, bring to the Process quality standard (that has been trusted by the industry for 30 years), and then deliver to you.", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='process-ohio-corporation' AND approved AND profile IS NULL;
UPDATE companies SET description='Production Equipment Services, LLC operates from Hartford, Wisconsin. Justman remains the owner, a small, cohesive team of skilled technicians.

The company provides on-site and in-house repair, upgrade, and maintenance services for industrial production equipment. Its capabilities span mechanical and electrical troubleshooting, machine tool alignment, press inspections, and preventative maintenance such as gib adjustments and lubrication system work. The shop also offers controls upgrades and retrofits, including PLC and HMI programming, VFD and servo drive commissioning, and network connectivity. In-house machining supports fabrication of guards and replacement parts, while machine guarding services cover risk assessments, light curtain installation, and control-reliable system design.

Customers come from general manufacturing, metal stamping, metal fabrication, and specialized sectors such as nuclear power. The company cites experience overhauling envelope folding machines and aligning nuclear turbines as examples of its range. It serves any industrial operation that relies on presses, machine tools, or automated production lines.

Justman emphasizes a vast vendor network that enables efficient and economical project execution, along with rapid response times and flexible scheduling. The business model was built on decades of hands-on repair experience and long-standing customer and vendor relationships.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Machine repair (metal stamping, metal fabrication, machine tool support and alignments)", "Breakdown service", "In-house machining", "On-site support", "Controls upgrade/retrofit (PLC, HMI, sensors, safety)", "VFD and servo drive installation and commissioning", "Network connectivity and equipment monitoring", "Equipment assessment and inspections", "Stop time monitoring and calibration", "Tonnage monitoring and calibration", "Light curtain validation", "Machine alignment", "Mechanical clearance checks to OEM standards", "Complete press inspections", "Mechanical and electrical troubleshooting", "Mechanical and electrical design", "Preventative maintenance (gib adjustments, oil and filter changes, validation of machine alignments, backup and update control firmware and software, development of maintenance staff and programs)", "Machine guarding (fabricate and install fixed guarding, light curtain installation, design and installation of control reliable systems, alternative presence sensing devices, risk assessment, stop time evaluation)", "Mechanical upgrade/retrofit (bearing evaluation and replacement, lubrication systems)"], "industries": ["Manufacturing", "Industrial manufacturing", "Nuclear power", "Metal stamping", "Metal fabrication"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Vast vendor network for efficient, economical project execution", "Rapid response and flexible scheduling", "On-site repair with fully equipped technicians", "In-house machining for guard fabrication and replacement parts", "Decades of hands-on machine repair experience"], "facts_used": ["Company name: Production Equipment Services, LLC -> db", "Headquarters: Hartford, Wisconsin -> db", "Owner: Keith Justman -> /about-us", "Founded: early 1990s (Keith Justman learned trade) -> /about-us", "Services: machine repair, controls upgrade, equipment assessment, troubleshooting, design, preventative maintenance, machine guarding, mechanical upgrade -> /services", "In-house machining capability -> /services", "On-site support with fully equipped technicians -> /", "Industries served: manufacturing, metal stamping, metal fabrication, nuclear -> /about-us, /services", "Business model: vast vendor base for efficient/economical execution -> /about-us", "Rapid response and flexible schedules -> /services", "Staff: small, cohesive, skilled team -> /about-us"], "company_type": "Installer / service company", "makes_products": "no", "type_evidence": "From overhauling and portably machining envelope folding machines to scraping for final alignments of nuclear turbines, our staff has a vast amount of exposure and experience.", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='production-equipment-services-llc' AND approved AND profile IS NULL;
UPDATE companies SET description='Professional Metal Fabricators (PMF) operates from Jefferson City, Missouri, serving industrial clients across the Midwest. The company does not disclose its founding year or ownership structure, but emphasizes a workforce with over 15 years of certified welding expertise and more than 120 years of combined experience in fabrication, layout, and equipment installation.

PMF specializes in industrial sheet metal fabrication, working with materials ranging from 20-gauge to 1-3/4-inch thick black iron, stainless steel, and aluminum. Its certified welders are qualified in SMAW, GMAW, GTAW, and FCAW processes, supported by certified welding inspectors. The shop provides design, construction, and construction management services, including fabrication of kitchen hoods, ductwork, air handlers, dust collection systems, platforms, handrails, spouting, chutes, transitions, bin clusters, mixers, ovens, bucket elevators, paddle drag systems, grease duct, insulated panels, airlock systems, and chainvey systems. The company also performs equipment setting, demolition, and installation.

The company serves a range of industrial sectors, including sanitary facilities, feed mill facilities, quarries and mines, bulk material handling facilities, production facilities, and local farms. Projects extend throughout Missouri and surrounding states.

PMF cites a guiding principle: "If you take care of your customers and employees, and do top quality work in a timely manner then the rest will fall into place." The firm highlights its certified welding inspectors, licensing, and insurance as markers of reliability.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Industrial sheet metal fabrication", "Welding (SMAW, GMAW, GTAW, FCAW)", "Fabricating and layout", "Equipment installation", "Design and construction management", "Dust collection system fabrication", "Ductwork fabrication", "Platform and handrail fabrication", "Spouting and chute fabrication", "Bin cluster fabrication", "Mixer and oven fabrication", "Bucket elevator fabrication", "Paddle drag system fabrication", "Grease duct fabrication", "Insulated panel installation", "Airlock system fabrication", "Chainvey system fabrication", "Demolition", "Equipment setting"], "industries": ["Sanitary facilities", "Feed mill facilities", "Quarries", "Mines", "Bulk material handling facilities", "Production facilities", "Local farms", "Industrial facilities"], "materials": ["Black iron", "Stainless steel", "Aluminum"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Certified welders qualified in SMAW, GMAW, GTAW, and FCAW", "Certified Welding Inspectors on staff", "Over 120 years of combined experience in fabrication, layout, and equipment installation", "Licensed and insured", "Serves Missouri and surrounding states"], "facts_used": ["Location: Jefferson City, MO -> db", "Specializes in industrial sheet metal -> /", "Works with 20ga-1-3/4\" Black iron, Stainless, Aluminum -> /", "Certified welders in SMAW, GMAW, GTAW, FCAW -> /", "120+ years combined experience in fabricating, layout, equipment installation -> /", "Certified Welding Inspectors, Licensed and Insured -> /", "Industries served: sanitary facilities, feed mill facilities, quarries and mines, bulk material handling facilities, production facilities, local far